cd ~/.minimax/v2/sessions && python3 - <<'EOF'
import json,glob,os,collections,statistics
tools=collections.Counter(); errs=collections.Counter()
dur=[]; turns=[]; interval=[]
single=0; big=0
for mf in glob.glob("*/*/*/*/messages.jsonl"):
    ats=[]; ts=[]; tn=set()
    for line in open(mf):
        line=line.strip()
        if not line: continue
        d=json.loads(line); m=d["message"]; r=m.get("role")
        if r=="assistant":
            ats.append(m.get("timestamp"))
            for c in m.get("content",[]):
                if isinstance(c,dict) and c.get("type")=="toolUse": tools[c.get("name")]+=1
        if r=="toolResult":
            tools[m.get("toolName")]+=0
            if m.get("isError"): errs[m.get("toolName")]+=1
        if m.get("timestamp"): ts.append(m["timestamp"])
        if d.get("turn_id"): tn.add(d["turn_id"])
    if ts: dur.append((max(ts)-min(ts))/60000)
    turns.append(len(tn))
    ats=[a for a in ats if a]
    for a,b in zip(sorted(ats),sorted(ats)[1:]): interval.append((b-a)/1000)
print("tool calls (top 12):")
for k,v in tools.most_common(12):
    print(f"  {str(k):<22} {v:>5}   errors {errs.get(k,0)}")
print("\nerror rate by tool:", dict(errs.most_common(8)))
print(f"\nsession wall-clock min: mean {statistics.mean(dur):.1f}  median {statistics.median(dur):.1f}  max {max(dur):.1f}")
print(f"turns/session: mean {statistics.mean(turns):.1f} median {statistics.median(turns)} max {max(turns)}")
print(f"gap between consecutive assistant msgs (s): median {statistics.median(interval):.1f} mean {statistics.mean(interval):.1f} p90 {sorted(interval)[int(.9*len(interval))]:.1f}")
EOF

